const pending = $input.all().filter(item => {
  const status = String(item.json.Status || '').trim().toLowerCase();
  const hasRequiredFields = item.json.ID && item.json.Source_URL;
  const alreadyExtracted = String(item.json.Screenshots || '').trim() || String(item.json.Extracted_Content || '').trim();
  return status === 'pending' && hasRequiredFields && !alreadyExtracted;
});

return pending.slice(0, 1);

const inputItems = $input.all();
const output = [];
const env = (typeof process !== 'undefined' && process.env) ? process.env : {};
const rewriteEnabled = ['1', 'true', 'yes'].includes(String(env.SCRIPT_REWRITE_ENABLED || 'true').trim().toLowerCase());
const model = String(env.SCRIPT_REWRITE_MODEL || 'gemini-2.5-flash-lite').trim();

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function sanitizeForSpeech(value) {
  return cleanText(value)
    .replace(/^Bai dang Threads nay dang gay chu y nhu sau:\s*/i, '')
    .replace(/^Mo dau cau chuyen nhu sau:\s*/i, '')
    .replace(/^Dien bien tiep theo la:\s*/i, '')
    .replace(/^Sau do, nguoi viet ke tiep rang:\s*/i, '')
    .replace(/^Chi tiet dang chu y o phan sau la:\s*/i, '')
    .replace(/^Comment dau tien noi rang:\s*/i, '')
    .replace(/^Mot y kien khac lai cho rang:\s*/i, '')
    .replace(/^Con co nguoi bo sung them la:\s*/i, '')
    .replace(/^Mot binh luan nua nhan manh rang:\s*/i, '')
    .replace(/^Y kien cuoi cung cho thay:\s*/i, '')
    .replace(/^(?:Pinned\s+)?(?:@?[A-Za-z0-9_.]+(?:\s+[A-Za-z0-9_.&'/-]+){0,8})\s+\d+\s*[smhdw]\b\s*/i, '')
    .replace(/\(?\s*\d+\s*\)?\s*(?:\/\s*\d+\s*)?(?:\d+(?:[.,]\d+)?[KMkm]?\s*){2,6}(?:to\s+[A-Za-z0-9_.\s-]+)?\.{0,3}\s*$/i, ' ')
    .replace(/\(?\s*\d+\s*\)?\s*(?:\/\s*\d+\s*)?(?:to\s+[A-Za-z0-9_.\s-]+)?\.{0,3}\s*$/i, ' ')
    .replace(/\bto\s+[A-Za-z0-9_.\s-]+\.{0,3}\s*$/i, ' ')
    .replace(/(^|\s)@\S+/g, ' ')
    .replace(/\b\d+\s*[smhdw]\b/gi, ' ')
    .replace(/[\u{1F300}-\u{1FAFF}]/gu, ' ')
    .replace(/[#*_`~|^]+/g, ' ')
    .replace(/[\\/]+/g, ' ')
    .replace(/\*{2,}/g, ' ')
    .replace(/\b(reply|like|share|repost|translate|view activity|top|pinned)\b/gi, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

function limitText(value, maxLength) {
  const text = cleanText(value);
  if (text.length <= maxLength) return text;
  const shortened = text.slice(0, maxLength);
  const lastBreak = Math.max(shortened.lastIndexOf('. '), shortened.lastIndexOf('! '), shortened.lastIndexOf('? '), shortened.lastIndexOf(', '), shortened.lastIndexOf(' '));
  return cleanText(shortened.slice(0, lastBreak > 40 ? lastBreak : maxLength));
}

function dedupeTexts(values) {
  const result = [];
  const seen = new Set();
  for (const value of values || []) {
    const text = cleanText(value);
    const key = text.toLowerCase().replace(/[^0-9a-z\u00c0-\u1ef9]+/g, '');
    if (!text || !key || seen.has(key)) continue;
    seen.add(key);
    result.push(text);
  }
  return result;
}

function normalizeTextArray(values, maxLength, maxItems) {
  const items = Array.isArray(values) ? values : [];
  const texts = items
    .map((item) => limitText(sanitizeForSpeech(item && item.text), maxLength))
    .filter((text) => text && text.replace(/\s/g, '').length >= 12);
  return dedupeTexts(texts).slice(0, maxItems);
}

function normalizeSegmentObjects(values, maxLength, maxItems, allowedTypes = []) {
  const items = Array.isArray(values) ? values : [];
  const result = [];
  const seen = new Set();

  for (const item of items) {
    const type = cleanText(item && item.type).toLowerCase() || 'segment';
    if (allowedTypes.length && !allowedTypes.includes(type)) continue;

    const text = limitText(sanitizeForSpeech(item && item.text), maxLength);
    const key = text.toLowerCase().replace(/[^0-9a-z\u00c0-\u1ef9]+/g, '');
    if (!text || !key || text.replace(/\s/g, '').length < 12 || seen.has(key)) continue;

    seen.add(key);
    result.push({ type, text });
    if (result.length >= maxItems) break;
  }

  return result;
}

function splitStorySegments(post, continuations) {
  const postParts = String(post || '')
    .split(/\n{2,}/)
    .map((part) => limitText(sanitizeForSpeech(part), 900))
    .filter(Boolean);
  const continuationParts = normalizeTextArray(continuations, 900, 12);
  const combined = continuationParts.length ? [...postParts, ...continuationParts] : postParts;
  return dedupeTexts(combined.filter(Boolean)).slice(0, 16);
}

function buildFallback(sourceSegments) {
  const lines = dedupeTexts((sourceSegments || []).map((item) => limitText(sanitizeForSpeech(item), 900)).filter(Boolean));
  return lines.join('\n').slice(0, 8000);
}

for (const item of inputItems) {
  const source = item.json;
  const extractedRaw = String(source.Extracted_Content || '').trim();
  let extracted = {};
  try {
    extracted = extractedRaw ? JSON.parse(extractedRaw) : {};
  } catch (error) {
    extracted = {};
  }

  const post = limitText(sanitizeForSpeech(extracted.post_text || ''), 8000);
  const segmentObjects = normalizeSegmentObjects(extracted.segments, 900, 16);
  const storySegments = segmentObjects.length
    ? segmentObjects.filter((item) => item.type === 'post' || item.type === 'continuation').map((item) => item.text)
    : splitStorySegments(post, extracted.continuations);
  const rawComments = segmentObjects.length
    ? segmentObjects.filter((item) => item.type === 'comment').map((item) => item.text)
    : normalizeTextArray(extracted.comments, 320, 8);
  const mode = cleanText(extracted.content_mode || '') || (storySegments.length >= 2 ? 'story' : (rawComments.length >= 2 ? 'discussion' : 'general'));
  const comments = mode === 'story' ? rawComments.slice(0, 2) : rawComments;
  const sourceSegments = mode === 'story'
    ? dedupeTexts([...storySegments, ...comments].filter(Boolean)).slice(0, 16)
    : (segmentObjects.length
      ? segmentObjects.map((item) => item.text)
      : (storySegments.length ? dedupeTexts([...storySegments, ...comments].filter(Boolean)).slice(0, 16) : dedupeTexts([post, ...comments].filter(Boolean)).slice(0, 16)));
  const rawScript = limitText(String(source.Narrator_Script || ''), 8000);
  const fallbackScript = buildFallback(sourceSegments) || rawScript || post;
  const note = cleanText(source.Note || '');
  const prompt = [
    'You are an expert short-form video script editor for Vietnamese TTS normalization.',
    'Your job is to minimally normalize the source text so a Vietnamese TTS voice can read it correctly and naturally, while preserving the original meaning, order, and segment structure.',
    'The input may include POST_TONG_HOP, STORY_SEGMENTS, SOURCE_SEGMENTS, and COMMENTS. STORY_SEGMENTS are continuation parts of the same story thread; COMMENTS are outside reactions or opinions.',
    'Preserve chronology strictly. Keep one output line per source segment whenever possible so narration timing can stay aligned with screenshots. Keep line breaks between segments unless the source is obviously fragmented.',
    'Allowed edits only: fix obvious typos, restore Vietnamese diacritics when clear, expand common abbreviations or shorthand so TTS can read them correctly, and remove noisy UI fragments.',
    'Expand Vietnamese teen/slang shorthand when clear: t = tao, m = may, b?n t = bon tao, mng = moi nguoi, k/ko/kh = khong, r = roi, nma = nhung ma, ny = nguoi yeu, dt/dt = dien thoai, dh = du hoc or dai hoc by context.',
    'Pronoun style is mandatory: when the source uses t or b?n t, write tao and b?n tao. Do not rewrite tao into to, toi, minh, to, t?, b?n t?, chúng tôi, or chúng t?.',
    'Examples of acceptable normalization when the meaning is clear: ck to chong, vk to vo, ko or k to khong, mn or mng to moi nguoi, mik or mk to minh, ny to nguoi yeu, dc or dc to duoc.',
    'Remove Threads UI/metric fragments such as like/comment/share counts, page markers, author context like to username, and navigation comments like de nghi chu tus de so len truoc.',
    'Do not shorten the content unless it is clearly duplicated or broken UI noise. If the source is long, keep the full meaningful content.',
    'Do not add framing phrases, filler connectors, commentary, summarizer language, dramatic transitions, conclusions, or new information that is not present in the source.',
    'If a slang term is ambiguous, keep it close to the original instead of guessing.',
    'If COMMENTS exist, use them only when they add meaningful context or reaction. If there are no useful comments, do not invent any.',
    'The final script must be written in natural Vietnamese, with short complete sentences, smooth flow, no bullet points, no markdown, and no ending question like Ban nghi sao.',
    'Return valid JSON only with exactly this schema: {"script":"..."}.',
  ].join(' ');

  output.push({
    json: {
      ...source,
      _rewrite: {
        enabled: rewriteEnabled,
        prompt,
        post,
        story_segments: storySegments,
        source_segments: sourceSegments,
        comments,
        fallback_script: fallbackScript,
        prior_note: note,
        model,
        mode,
      },
    },
  });
}

return output;

const output = [];

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function cleanLines(value) {
  return String(value || '')
    .replace(/\r/g, '')
    .split('\n')
    .map((line) => line.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
    .join('\n');
}

function normalizePronouns(value) {
  return String(value || '')
    .replace(/\bb?n\s+t?\b/gi, 'b?n tao')
    .replace(/\bt?i\s+t?\b/gi, 't?i tao')
    .replace(/\bt?\b/gi, 'tao');
}

function normalizeScript(value) {
  return cleanLines(normalizePronouns(String(value || '')))
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```$/i, '')
    .replace(/^['\"]+|['\"]+$/g, '')
    .replace(/^script\s*:\s*/i, '')
    .replace(/^[\-*â€¢]+\s*/gm, '')
    .trim();
}

function parseJsonCandidate(text) {
  const cleaned = cleanText(text);
  if (!cleaned) return '';

  const fencedMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const jsonSource = fencedMatch ? fencedMatch[1] : cleaned;
  const candidates = [jsonSource, ...(jsonSource.match(/\{[\s\S]*?\}/g) || [])];

  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (typeof parsed === 'string') return normalizeScript(parsed);
      if (parsed && typeof parsed.script === 'string') return normalizeScript(parsed.script);
      if (parsed && typeof parsed.narrator_script === 'string') return normalizeScript(parsed.narrator_script);
    } catch (error) {
      continue;
    }
  }

  return '';
}

function extractTextDeep(value, bucket = []) {
  if (typeof value === 'string') {
    const cleaned = cleanText(value);
    if (cleaned) bucket.push(cleaned);
    return bucket;
  }

  if (!value || typeof value !== 'object') return bucket;

  if (Array.isArray(value)) {
    value.forEach(entry => extractTextDeep(entry, bucket));
    return bucket;
  }

  const preferredKeys = ['script', 'narrator_script', 'text', 'output', 'generatedText', 'content', 'message'];
  preferredKeys.forEach(key => {
    if (typeof value[key] === 'string') {
      const cleaned = cleanText(value[key]);
      if (cleaned) bucket.push(cleaned);
    }
  });

  Object.values(value).forEach(entry => {
    if (entry && typeof entry === 'object') {
      extractTextDeep(entry, bucket);
    }
  });

  return bucket;
}

function extractGeminiScript(data) {
  if (!data || typeof data !== 'object') return '';

  const possibleJsonSources = [
    data.script,
    data.text,
    data.output,
    data.generatedText,
    typeof data.response === 'string' ? data.response : '',
    typeof data.content === 'string' ? data.content : '',
    typeof data.message === 'string' ? data.message : '',
  ].filter(Boolean);

  for (const source of possibleJsonSources) {
    const parsed = parseJsonCandidate(source);
    if (parsed) return parsed;
  }

  const deepTexts = extractTextDeep(data, []);
  for (const text of deepTexts) {
    const parsed = parseJsonCandidate(text);
    if (parsed) return parsed;
  }

  const combined = normalizeScript(deepTexts.join('\n'));
  return combined;
}

for (const item of $input.all()) {
  const rewrite = item.json._rewrite || {};
  const note = cleanText(rewrite.prior_note || item.json.Note || '');
  const disabled = !rewrite.enabled;
  const candidate = (((item.json.candidates || [])[0]) || {});
  const finishReason = cleanText(candidate.finishReason || item.json.finishReason || '');
  const script = extractGeminiScript(item.json);
  const truncated = finishReason.toUpperCase() === 'MAX_TOKENS';
  const tooShort = script && script.length < 80;
  const invalidObjectLeak = /^\[object Object\]/i.test(script);

  if (disabled) {
    item.json.Narrator_Script = String(rewrite.fallback_script || '').slice(0, 8000);
    item.json.Note = cleanText(`${note} | AI rewrite skipped: disabled by SCRIPT_REWRITE_ENABLED`);
  } else if (script && !truncated && !tooShort && !invalidObjectLeak) {
    item.json.Narrator_Script = script.slice(0, 8000);
    item.json.Note = cleanText(`${note} | AI rewrite ready gemini=${rewrite.model}`);
  } else {
    const reason = truncated
      ? 'MAX_TOKENS'
      : invalidObjectLeak
        ? 'invalid Gemini object output'
        : (tooShort ? 'short Gemini response' : 'empty Gemini response');
    item.json.Narrator_Script = String(rewrite.fallback_script || script || '').slice(0, 8000);
    item.json.Note = cleanText(`${note} | AI rewrite fallback: ${reason} gemini=${rewrite.model}`);
  }

  delete item.json._rewrite;
  output.push(item);
}

return output;
